const FIXTURE_ID: &str = "planned:repository-directive:i195-parity-feature-completeness";

fn language_features() -> Value {
    let mut dir = PathBuf::from(env!("CARGO_MANIFEST_DIR"));
    while !dir.join("parity/language-features.lino").is_file() {
        assert!(dir.pop(), "parity/language-features.lino should exist");
    }
    let text = fs::read_to_string(dir.join("parity/language-features.lino"))
        .expect("parity/language-features.lino should be readable");
    meta_language::read_structured_data_lino(&text)
        .expect("parity/language-features.lino should be linked structured data")
}

#[test]
fn export_parity_rust_has_every_listed_feature() {
    let _ = meta_language::AccessMode::is_mutable;
    let _ = meta_language::AccessMode::is_read_only;
    let _ = meta_language::AccessMode::label;
    let _ = meta_language::LinkId::as_u64;
    let _ = meta_language::LinkNetwork::as_read_only;
    let _ = meta_language::LinkNetwork::freeze;
    let _ = meta_language::LinkNetwork::insert_concept_record;
    let _ = meta_language::LinkNetwork::parse_engine;
    let _ = meta_language::ProgramRepresentation::from_snapshot;
    let _ = meta_language::ProgramRepresentation::serialize_snapshot;
    let _ = meta_language::SyntaxTree::render;
    let _ = meta_language::grammar::inference::active::Dfa::accepts;
    let features = language_features();
    let listed = features["javascriptExports"]
        .as_object()
        .expect("javascriptExports should be an object");
    assert_eq!(listed.len(), EXPORTS.len(), "each export is listed");
    for (name, rust, kind) in EXPORTS {
        let entry = &listed[*name];
        assert_eq!(entry["rust"], *rust, "{name} maps to {rust}");
        assert_eq!(entry["kind"], *kind, "{name} is a {kind}");
    }
    record(&Observation {
        requirement_id: "I195-PARITY-FEATURE-COMPLETENESS",
        suffix: "behavior",
        fixture_id: FIXTURE_ID,
        fixture_file: "docs/vision.md",
        assertions: &["everyPublicExportListed", "rustHasEveryFeature"],
        test_name: "javascript_export_parity::export_parity_rust_has_every_listed_feature",
    });
}
